-- EGESER PREFABRIK - KURUMSAL URUNLERE PLAN OZETI - 20261125
-- 8 yemekhane + 16 ofis: kat planlarindan okunan kapasite, bolumler ve dis olculer urun aciklamasinin SONUNA eklenir;
-- arama sonucu aciklamasi (meta_description) bu bilgilerle yeniden yazilir.
-- Urun adi, URL, fiyat, gorseller ve mevcut aciklama metni DEGISMEZ (yalnizca sonuna ekleme yapilir).
-- 39 m2 ofis icin dogru plan gorselleri (egeser_39m2_kat_plani_yukle.zip) ayrica yuklenmelidir.
-- Once yedek alir; ikinci kez calistirilirsa CREATE TABLE hatasiyla durur. Geri almak icin: 38_PLAN_OZETI_GERI_AL.sql
SET NAMES utf8mb4;

CREATE TABLE oc_product_description_backup_plan_20261125 AS SELECT * FROM oc_product_description WHERE product_id IN (177,178,179,180,181,182,183,184,160,161,162,163,164,165,166,167,168,169,170,171,172,173,174,176);

